// Offline support. When you are online the newest files are fetched first (so an updated app shows up on the
// next open, never an old saved copy); the saved copy is only used when there is no connection.
// VERSION and ASSETS are generated by scripts/stamp-sw.mjs (runs on `npm start` and on every deploy):
// VERSION is a fingerprint of the app files, so any change makes phones fetch the new version.
const VERSION = 'chord-coach-db3fde12fa';
const ASSETS = [
  './',
  'icons/icon-180.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon.svg',
  'index.html',
  'js/analyze.js',
  'js/app.js',
  'js/audio.js',
  'js/dom.js',
  'js/keyboard.js',
  'js/player.js',
  'js/rhythm.js',
  'js/sheet.js',
  'js/store.js',
  'js/style.js',
  'js/theory.js',
  'js/ultimate-guitar.js',
  'js/views/chords.js',
  'js/views/quiz.js',
  'js/views/sheets.js',
  'js/views/songs.js',
  'manifest.webmanifest',
  'reset.html',
  'styles.css',
];

self.addEventListener('install', e => {
  // cache: 'reload' skips the browser's own HTTP cache, so a new version can never save old files.
  e.waitUntil(
    caches.open(VERSION)
      .then(c => Promise.all(ASSETS.map(a => c.add(new Request(a, { cache: 'reload' })))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return;
  e.respondWith((async () => {
    const cache = await caches.open(VERSION);
    try {
      const fresh = await fetch(e.request, { cache: 'no-cache' }); // ask the server whether the file changed
      if (fresh.ok) cache.put(e.request, fresh.clone());
      return fresh;
    } catch {
      // Offline: use the saved copy (the page itself if it was a page visit).
      return (await cache.match(e.request, { ignoreSearch: true })) || (await cache.match('index.html')) || Response.error();
    }
  })());
});
